// work.comment.add — E5 AC2: comment on a project; @mentions notify active staff only. Generated by
// `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aClientActor, aStaffActor, countRows } from '@ocs/testing';
import { Forbidden, NotFound, ValidationFailed } from '../../kernel/index.ts';
import { addComment } from '../commands/add-comment.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const pm = aStaffActor({ roles: ['pm'] });
const rnd = aStaffActor({ roles: ['rnd'] });
const gone = aStaffActor({ roles: ['sales'] });
const outsider = aStaffActor({ roles: ['admin'] });
let w: WorkWorld;
const input = (more: Record<string, unknown> = {}) => ({
  siteId: w.siteId,
  body: 'Ceiling height?',
  ...more,
});
const mentionEvents = (userId: string) =>
  countRows(w.testDb.url, `outbox WHERE event_type = 'work.comment.mentioned' AND payload->>'userId' = $1`, [
    userId,
  ]);

beforeAll(async () => {
  w = await openWorkWorld();
  await w.account(rnd);
  await w.account(gone, true);
  w.t.grant(pm, addComment.permission);
});

afterAll(async () => {
  await w.close();
});

describe('work.comment.add', () => {
  it('refuses an actor without the permission', async () => {
    await expect(w.t.kernel.execute(addComment, outsider, input(), 'test')).rejects.toBeInstanceOf(Forbidden);
  });

  it('refuses a blank comment and an unknown project', async () => {
    await expect(w.t.kernel.execute(addComment, pm, input({ body: ' ' }), 'test')).rejects.toBeInstanceOf(
      ValidationFailed,
    );
    await expect(
      w.t.kernel.execute(addComment, pm, input({ siteId: randomUUID() }), 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });

  it('mentions only active staff: never a client, an archived account or an unknown id', async () => {
    const clientUser = await w.account(aClientActor(randomUUID()));
    for (const who of [clientUser.id, gone.id, randomUUID()]) {
      await expect(
        w.t.kernel.execute(addComment, pm, input({ mentions: [who] }), 'test'),
      ).rejects.toBeInstanceOf(ValidationFailed);
    }
  });

  it('stores the comment on its project and queues one notice per mentioned person', async () => {
    const { id } = await w.t.kernel.execute(addComment, pm, input({ mentions: [rnd.id, rnd.id] }), 'test');
    expect(
      await countRows(w.testDb.url, `comment WHERE id = $1 AND site_id = $2 AND author_id = $3`, [
        id,
        w.siteId,
        pm.id,
      ]),
    ).toBe(1);
    expect(await mentionEvents(rnd.id)).toBe(1);
    expect(await countRows(w.testDb.url, 'audit_event WHERE command = $1', [addComment.name])).toBe(1);
  });
});
